// SensoreAppunti.swift: cambi degli appunti, evento 'appunti'. Mai il contenuto.
//
//   Timer 0,5 s su NSPasteboard.general.changeCount. Al cambio:
//     - tipi = pasteboard.types (solo i nomi dei tipi, MAI il contenuto);
//     - riservato se c'è un tipo org.nspasteboard.{Concealed,Transient,AutoGenerated}Type;
//     - app sorgente = app attiva (la mette l'Annotatore dal suo stato);
//     - selezione = l'AXSelectedText visto all'ultima copia (dal PonteAppunti), non dal
//       pasteboard; da lì l'Annotatore ricava le impronte con fonte 'selezione';
//     - len = lunghezza di quella selezione (così non si legge il contenuto del pasteboard).
//   L'Annotatore aggiorna Contesto.ultimoChangeCount e, se il filtro dà `pieno`, scrive l'evento.
//
// Il changeCount iniziale si prende all'avvio: non si annota ciò che era già negli appunti.

import AppKit
import Foundation

final class SensoreAppunti: NSObject, Sensore {
    let dip: Dipendenze
    let ponte: PonteAppunti
    private var timer: Timer?
    private var ultimoCC = 0

    static let riservati: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    init(dip: Dipendenze, ponte: PonteAppunti) {
        self.dip = dip
        self.ponte = ponte
        super.init()
    }

    func avvia() {
        ultimoCC = NSPasteboard.general.changeCount
        let t = Timer(timeInterval: 0.5, target: self, selector: #selector(controlla), userInfo: nil, repeats: true)
        t.tolerance = 0.1
        RunLoop.main.add(t, forMode: .common)
        timer = t
        dip.registro.salute(sensore: "appunti", stato: "ok")
    }

    func ferma() {
        timer?.invalidate()
        timer = nil
    }

    @objc private func controlla() {
        let pb = NSPasteboard.general
        let cc = pb.changeCount
        if cc == ultimoCC { return }
        ultimoCC = cc
        let tipi = (pb.types ?? []).map { $0.rawValue }
        let riservato = SensoreAppunti.riservato(tipi)
        let ts = oraMs()
        // La selezione è l'ultima vista a una copia: non si legge il contenuto del pasteboard.
        let selezione = riservato ? nil : ponte.preleva(entro: 3000, ts)
        let lunghezza = selezione?.count
        dip.annotatore.appunti(cc: cc, tipi: tipi, riservato: riservato, lunghezza: lunghezza, selezione: selezione, ts: ts)
    }

    // MARK: Puro (testato dal selftest)

    /// true se fra i tipi c'è un marcatore di contenuto riservato (NSPasteboard concealed/transient).
    static func riservato(_ tipi: [String]) -> Bool {
        for t in tipi where SensoreAppunti.riservati.contains(t) { return true }
        return false
    }
}
